{"content": "from pydantic import ConfigDict, model_validator
from pydantic.dataclasses import dataclass


StrictConfig = ConfigDict(
    str_strip_whitespace=True,
    validate_assignment=True,
)


@dataclass(config=StrictConfig)
class Point:
    label: str
    lat: float
    lon: float

    @model_validator(mode="after")
    def _check_and_normalize(self):
        if not (-90 <= self.lat <= 90 and -180 <= self.lon <= 180):
            raise ValueError("coordinates out of range")
        # Use object.__setattr__ to avoid re-triggering validate_assignment
        # (which would re-run this validator and recurse infinitely).
        object.__setattr__(self, "label", self.label.title())
        return self


def make_point(label, lat, lon) -> Point:
    return Point(label=label, lat=lat, lon=lon)
